using System;
using System.IO;
using System.Linq;
using System.Text.Json;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using NetworkHub.App;
using NetworkHub.Dns;
namespace NetworkHub.Desktop;
internal static class TestsWorkspace
{
    static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
    internal static void Run(Action<string,Action> test,Shell shell,AppFiles files)
    {
        test("Workspace migration preserves startup and independent selections",()=>{var s=JsonSerializer.Deserialize<UserSettings>("{\"ZapretSelected\":false,\"TgSelected\":true,\"StartWithWindows\":false}")!;s.Workspace.Normalize();Check(s.Workspace.Visible.Length==3&&!s.Workspace.DnsInGroup&&!s.StartWithWindows&&!s.ZapretSelected&&s.TgSelected,"Migration changed intent");});
        test("Workspace stable IDs normalize duplicates and preserve hidden primary",()=>{var s=new WorkspaceSettings{Order=new[]{"dns","dns","unsupported"},Visible=new[]{"tg","tg"},Primary="dns"};s.Normalize();Check(s.Order.SequenceEqual(new[]{"dns","zapret","tg"})&&s.Visible.SequenceEqual(new[]{"tg"})&&s.Primary=="dns","Identity or hidden assignment changed");});
        test("Workspace settings survive a fresh deserialize without DNS runtime state",()=>{var s=new UserSettings();s.Workspace.Visible=new[]{"dns"};s.Workspace.Order=new[]{"dns","tg","zapret"};s.Workspace.Primary="tg";s.Workspace.ManualHeight=true;s.Workspace.Height=623;s.Workspace.DnsInGroup=true;var n=s.Copy();Check(n.Workspace.Height==623&&n.Workspace.ManualHeight&&n.Workspace.Primary=="tg"&&n.Workspace.DnsInGroup&&n.Workspace.Visible.SequenceEqual(new[]{"dns"}),"Persistence lost");});
        test("Workspace auto height grows only with count and caps at 780 DIP",()=>{Check(WorkspaceSettings.AutoHeight(1)==510&&WorkspaceSettings.AutoHeight(2)==583&&WorkspaceSettings.AutoHeight(3)==656&&WorkspaceSettings.AutoHeight(100)==780,"Sizing policy");});
        test("Workspace group checkbox does not rewrite frozen startup selection",()=>{var saved=shell.Settings.Copy();try{shell.Settings.StartupZapret=true;shell.Find<CheckBox>("ZapretCheck").IsChecked=false;Check(!shell.Settings.ZapretSelected&&shell.Settings.StartupZapret==true,"Group selection changed startup");}finally{shell.Find<CheckBox>("ZapretCheck").IsChecked=saved.ZapretSelected;shell.ApplySettings(saved);}});
        test("Workspace reorders and hides rows without process or DNS writes",()=>{var saved=shell.Settings.Copy();try{var s=saved.Copy();s.Workspace.Primary="dns";s.Workspace.Order=new[]{"dns","tg","zapret"};s.Workspace.Visible=new[]{"tg","dns"};shell.ApplySettings(s);var list=shell.Find<StackPanel>("ModuleList");Check(list.Children.Count==2&&list.Children[0]==shell.Find<Border>("DnsRow")&&s.Workspace.Primary=="dns"&&shell.Runtime.LaunchCount==0,"Presentation changed runtime");}finally{shell.ApplySettings(saved);}});
        test("DNS acceptance archives original and performs zero system writes",()=>{var fake=TestsDns.Fixture();var original=fake.State;string dir=Path.Combine(files.Data,"adoption-"+Guid.NewGuid().ToString("N"));var store=new DnsFileJournalStore(dir,"safe-test");var tx=new DnsTransaction(fake,fake,store,"safe-test");var target=original.With(DnsFamily.IPv4,new(DnsMode.Manual,new[]{"83.220.169.155","212.109.195.93"},Array.Empty<string>()));tx.Apply(original,target,new[]{DnsFamily.IPv4},"comss");var old=store.Load(original.AdapterId)!;fake.State=original.With(DnsFamily.IPv4,new(DnsMode.Manual,new[]{"8.8.8.8","8.8.4.4"},Array.Empty<string>()));int writes=fake.Writes;var accepted=tx.AcceptCurrent(fake.State);Check(fake.Writes==writes&&!accepted.Active&&accepted.Before.SameConfiguration(fake.State),"Acceptance wrote DNS or lost baseline");var archive=Directory.GetFiles(Path.Combine(dir,"Archives"),"*.json",SearchOption.AllDirectories).Single();Check(JsonSerializer.Deserialize<DnsJournal>(File.ReadAllText(archive))!.Before.SameConfiguration(original),"First backup lost");var restarted=new DnsFileJournalStore(dir,"safe-test");Check(restarted.Load(original.AdapterId)!.Id==accepted.Id,"Restart lost baseline");tx.Apply(fake.State,target,new[]{DnsFamily.IPv4},"comss");tx.Restore(original.AdapterId,fake.State.Fingerprint());Check(fake.State.IPv4.Servers.SequenceEqual(new[]{"8.8.8.8","8.8.4.4"}),"Stale Xbox/original restored instead of accepted Google");});
        test("DNS acceptance refuses changed or unsupported snapshots before archive",()=>{var fake=TestsDns.Fixture();var before=fake.State;var store=new DnsFileJournalStore(Path.Combine(files.Data,"adoption-invalid"),"safe-test");var tx=new DnsTransaction(fake,fake,store,"safe-test");fake.State=before with{DependencyFingerprint="changed"};bool rejected=false;try{tx.AcceptCurrent(before);}catch(DnsException){rejected=true;}Check(rejected&&store.Load(before.AdapterId)==null&&fake.Writes==0,"Stale acceptance permitted");fake.State=before with{CanChange=false};rejected=false;try{tx.AcceptCurrent(fake.State);}catch(DnsException){rejected=true;}Check(rejected&&fake.Writes==0,"Unsupported acceptance permitted");});
        test("DNS acceptance cannot use a store without durable archival",()=>{var fake=TestsDns.Fixture();bool blocked=false;try{new DnsTransaction(fake,fake,new TestsDns.FakeStore(),"safe-test").AcceptCurrent(fake.State);}catch(DnsException){blocked=true;}Check(blocked&&fake.Writes==0,"Unarchived baseline permitted");});
        test("DNS archive disk failure leaves the original journal untouched",()=>{var fake=TestsDns.Fixture();var original=fake.State;string dir=Path.Combine(files.Data,"archive-fault-"+Guid.NewGuid().ToString("N"));var store=new DnsFileJournalStore(dir,"safe-test");var tx=new DnsTransaction(fake,fake,store,"safe-test");tx.Reapply(original,original,new[]{DnsFamily.IPv4},"custom");var old=store.Load(original.AdapterId)!;File.WriteAllText(Path.Combine(dir,"Archives"),"owned fault fixture");bool blocked=false;int writes=fake.Writes;try{tx.AcceptCurrent(fake.State);}catch(IOException){blocked=true;}Check(blocked&&store.Load(original.AdapterId)!.Id==old.Id&&fake.Writes==writes,"Archive failure replaced the original");});
    }
    internal static async Task Ui(Shell shell,AppFiles files,Func<string,Func<Task>,Task> test)
    {
        await test("Workspace order mode uses real arrow events and leaves assignment unchanged",async()=>{
            var saved=shell.Settings.Copy();int launches=shell.Runtime.LaunchCount;try{shell.Settings.Workspace.Primary="dns";shell.Workspace.OpenManager();var manager=shell.Window.OwnedWindows.Cast<Window>().Single(w=>w.FindName("Visibledns")!=null);var edit=LocalizedTree.Walk(manager).OfType<Button>().First(b=>b.Content?.ToString()==L.T("Change order…"));edit.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(shell.Workspace.Editing,"Order mode did not open");var grid=(Grid)shell.Find<Border>("DnsRow").Child;var arrows=grid.Children.OfType<StackPanel>().Single(p=>Equals(p.Tag,"workspace-order"));((Button)arrows.Children[0]).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(shell.Settings.Workspace.Order[1]=="dns"&&shell.Settings.Workspace.Primary=="dns","Reorder changed assignment");await shell.Workspace.Execute();Check(!shell.Workspace.Editing&&files.Load().Workspace.Order[1]=="dns"&&shell.Runtime.LaunchCount==launches,"Reorder launched or did not persist");}finally{shell.ApplySettings(saved);}
        });
        await test("Workspace DNS power uses verified session across close restart and foreign changes",async()=>{
            var saved=shell.Settings.Copy();var isolated=new AppFiles(Path.Combine(files.Root,"test-results/workspace-dns-"+Guid.NewGuid().ToString("N")));var fake=TestsDns.Fixture(isolated.Data);var original=fake.State;DnsManagerView.ReaderForTests=fake;DnsManagerView? view=null;
            try{
                view=new DnsManagerView(shell,isolated);view.ConfirmationForTests=_=>true;view.Window.Show();Check(!view.Applied,"Opening applied DNS");await view.Power(false);Check(view.Applied&&fake.Writes>0,"Power did not apply mock DNS");view.Window.Close();
                view=new DnsManagerView(shell,isolated);view.ConfirmationForTests=_=>true;view.Window.Show();Check(view.Applied,"Managed state lost after window restart");
                fake.State=original.With(DnsFamily.IPv4,new(DnsMode.Manual,new[]{"8.8.8.8","8.8.4.4"},Array.Empty<string>()));view.RefreshStatus();Check(!view.Applied&&((Button)view.Window.FindName("DnsResolve")).Visibility==Visibility.Visible,"Foreign change still marked applied");
                ((Button)view.Window.FindName("DnsResolve")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(30);int writes=fake.Writes;Check(!view.Applied,"Acceptance falsely marked applied");await view.Power(false);Check(view.Applied&&fake.Writes>writes,"Accepted session cannot apply");await view.Power(true);Check(!view.Applied&&fake.State.IPv4.Servers.SequenceEqual(new[]{"8.8.8.8","8.8.4.4"}),"Restored stale original instead of accepted baseline");
            }finally{view?.Window.Close();DnsManagerView.ReaderForTests=null;shell.ApplySettings(saved);}
        });
        await test("Workspace main row geometry and pinned footer for one two three modules",()=>{
            var saved=shell.Settings.Copy();try{foreach(string theme in new[]{"dark","light"})foreach(int count in new[]{1,2,3}){var s=saved.Copy();s.Theme=theme;s.Backdrop="solid";s.Workspace.Visible=WorkspaceSettings.Modules.Take(count).ToArray();s.Workspace.ManualHeight=false;shell.ApplySettings(s);shell.Window.UpdateLayout();Check(shell.Window.Height==WorkspaceSettings.AutoHeight(count),"Auto height incorrect");var button=shell.Find<Button>("Settings");Check(button.TranslatePoint(new Point(0,button.ActualHeight),shell.Window).Y<=shell.Window.ActualHeight,"Footer clipped");Check(shell.Find<ScrollViewer>("MainScroll").ScrollableHeight==0,"Unnecessary scrolling");SelfTests.Capture(shell.Window,Path.Combine(files.Data,$"workspace-{theme}-{count}.png"));}}finally{shell.ApplySettings(saved);}return Task.CompletedTask;
        });
    }
}
